import { chatJson, withOp, type AiCtx } from "./llm";
import { fetchText } from "./fetch";
import { CATEGORY_LABELS, SLOT_BRIEF, SLOT_CLASSIFY, type NewsSettings } from "./types";
import { embedCode, type ClusterResearch } from "./research";

/**
 * Этап 2: украинская суть карточки и «почему зайдёт у нас» (в прогоне, пачками), углы по кнопке «В работу»,
 * ТЗ для Claude по выбранному углу — в стиле редакции проекта. ТЗ собирается из JSON модели в одинаковый markdown.
 */

export type SourceForAi = { domain: string; title: string; lead: string; url: string; tier: string; at: Date };
export type ClusterForAi = { id: string; title: string; category: string | null; subcategory: string | null; entity: string | null; signals: string[]; sources: SourceForAi[] };
export type Summary = { id: string; titleUk: string; summaryUk: string; whyUs: string };
export type Angle = { title: string; angle: string; why: string; novelty: number; usefulness: number; kind: string; format?: string };
export type OurArticle = { title: string; url: string };

const s = (v: unknown, max = 2000) => String(v ?? "").trim().slice(0, max);
const n15 = (v: unknown) => Math.max(1, Math.min(5, Math.round(Number(v) || 3)));
const srcText = (c: ClusterForAi, perLead = 500) =>
  c.sources.slice(0, 8).map((x, i) => `${i + 1}. [${x.tier === "world" ? "світове медіа" : "українське медіа"}] ${x.domain}: ${x.title}${x.lead ? ` — ${x.lead.slice(0, perLead)}` : ""}`).join("\n");

/** Суть по-украински для пачки до 5 кластеров (модель углов и ТЗ: дешёвая давала суржик). */
export async function summarizeClusters(ctx: AiCtx, st: NewsSettings, list: ClusterForAi[]): Promise<Summary[]> {
  const system = `Ти редактор українського медіа. Про сайт: ${st.siteAbout}
Пиши лише літературною українською (жодних русизмів і суржику: не «зачоска», «соцсетях», «старыми» — а «зачіска», «соцмережах», «старими»). Імена — як прийнято в українських медіа (Періс Гілтон, Кім Кардаш'ян, Зендея).
Для кожної новини (id) дай:
- title_uk: нейтральний заголовок українською до 90 символів (якщо джерела англійською — переклади суть, не дослівно);
- summary_uk: 2–3 речення українською — хто, що, де, коли; лише факти з джерел, спірне познач «за даними …»;
- why_us: 1–2 речення українською — чому це зайде саме нашій аудиторії і на чому зробити акцент (практична користь, впізнаваний герой, образ, ціна, тренд). Якщо тема слабка для нас — чесно скажи чому.
Поверни лише JSON: {"items":[{"id":"…","title_uk":"…","summary_uk":"…","why_us":"…"}]}`;
  const user = list.map((c) => `### id: ${c.id}\nКатегорія: ${c.category ? CATEGORY_LABELS[c.category] ?? c.category : "—"}${c.entity ? `; герой: ${c.entity}` : ""}\nСигнали: ${c.signals.join("; ") || "—"}\nДжерела:\n${srcText(c, 400)}`).join("\n\n");
  const j = await chatJson(withOp(ctx, "summary"), SLOT_BRIEF, system, user, st.briefModel, 2500);
  const items = Array.isArray(j.items) ? (j.items as Record<string, unknown>[]) : [];
  return items
    .map((r) => ({ id: s(r.id, 64), titleUk: s(r.title_uk, 300), summaryUk: s(r.summary_uk, 1500), whyUs: s(r.why_us, 1000) }))
    .filter((x) => list.some((c) => c.id === x.id) && x.summaryUk);
}


/**
 * Формат статьи под Discover. Discover показывает материал по интересу к герою и картинке, а не по запросу:
 * побеждает момент + одна наша мысль, а не справочник. Формат выбирается по типу повода, объём — по формату.
 */
export const FORMATS: Record<string, { label: string; words: string; when: string }> = {
  moment: { label: "Момент", words: "250–400 слів", when: "фото/образ/вихід зірки, одна подія, 1–3 факти: новина + що це за образ або стрижка + одна наша ремарка" },
  news: { label: "Новина", words: "300–450 слів", when: "подія з кількома фактами: заручини, прем'єра, запуск, скандал — що сталося, що відомо, що далі" },
  look: { label: "Розбір образу", words: "350–500 слів", when: "образ варто розібрати по речах: бренд, ціна, де схоже купити в Україні — коротко, по пунктах" },
  howto: { label: "Як повторити", words: "450–650 слів", when: "лише якщо тренд справді масовий і читачка захоче повторити: 5–7 кроків, без енциклопедії" },
  list: { label: "Підбірка", words: "400–600 слів", when: "премія, тиждень моди, Геловін — 5–10 образів, по 1–2 речення на кожен, фото головне" },
  context: { label: "Що за цим стоїть", words: "400–550 слів", when: "новина має передісторію, яку читачка не знає: що було раніше, чому зараз, що буде" },
};
const FORMAT_KEYS = Object.keys(FORMATS);

const DISCOVER_RULES = `Правила Discover (Україна; за документацією Google 2026 і даними по стрічці):
- Discover — стрічка за інтересами, не пошук. Читачка побачить картинку і заголовок; клікне, якщо впізнає героя і зрозуміє, що саме нового. ~80 % трафіку Discover дають сутності: герой або бренд у перших словах заголовка. Жодних «гайдів під запит».
- Заголовок має «передавати суть матеріалу» (Google, лютий 2026): без клікбейту, без приховування головного («ви не повірите, що вона зробила»), без «шок/сенсація», без питання замість відповіді (заголовки-питання після оновлення Discover 2026 втратили покази), без трикрапки й капсу. Обіцянка заголовка закривається в першому абзаці.
- Довжина заголовка (H1) 60–95 символів: конкретна нова деталь (яка сукня, скільки років, що сказала), не стислий «Герой: подія». Герой і гачок — у перших ~60 символах: на телефоні картка Discover обрізає хвіст. Title для <title> коротший і окремий.
- Перші два речення тексту відповідають на «хто, що, коли, де» і дають той факт, який обіцяв заголовок, плюс звідки це відомо («написала в Instagram», «в інтерв'ю …»). Лід не повторює заголовок слово в слово.
- Оригінальність (критерій Google «помічний контент»): у тексті має бути те, чого нема в переказах, — точна цитата героя, дата й цифра, посилання на першоджерело, український контекст. Переказ чужої статті іншими словами — не оригінальність.
- Текст легкий: 250–450 слів, абзаци по 1–3 речення (у конкурентів 9–15 коротких абзаців), 1–2 змістовні H2 лише якщо текст довший за 300 слів. Одна наша думка або деталь, а не чотири розділи. Жодних списків «для круглого обличчя», цін по містах, історії стрижки з 1953 року.
- Що збирає перегляди (заміри по українських сайтах): особисте — народження дітей, розлучення, зізнання, операції, тіло, стосунки — у 10–50 разів більше, ніж образи й тренди. Образ зірки працює, коли в ньому є конкретна деталь (бренд, ціна, що сказав чоловік), а не «стильний вихід».
- Свіжість: >70 % кліків Discover приходять у першу добу після публікації; картка новини живе години. Писати сьогодні. Не перевипускати старі тексти з новою датою.
- Факти лише з джерел. Деталі, яких нема в джерелах (ціни в салонах, назви засобів), не вигадувати — або прибрати, або позначити як завдання автору знайти.
- Фото вирішує: 1200 px+ по ширині, 16:9, обличчя героя великим планом з емоцією або жива сцена; без колажів, логотипів і тексту на картинці. Під кожне фото — ім'я файлу та alt з героєм.
- Права на фото: головне фото лише з пресматеріалів бренду чи організатора, фотобанку за ліцензією, Wikimedia Commons (CC) або власної зйомки; пост героя — тільки вбудуванням (embed), не скриншотом. Фото з Daily Mail, Page Six, People та будь-яких сайтів-джерел брати заборонено. Під фото — підпис із джерелом і ліцензією.
- Сенсаційність заборонена окремо (Google, березень 2026): не грати на нездоровій цікавості, пікантності чи обуренні. Смерть, хвороба, аварія, насильство — у заголовку факт і людина, без смакування подробиць («помер у 86 років», а не «страшні останні дні»).
- На кого посилаємось (правило редакції): світові медіа — можна згадати й поставити посилання, ми перші в Україні, хто про це пише. Українські медіа — прямі конкуренти: їх НЕ згадуємо («як пише ТСН») і НЕ посилаємось, щоб не підсилювати; їхні факти беремо, лише перевіривши в першоджерелі. Першоджерело (пост героя, офіційна заява, інтерв'ю на YouTube, пресреліз) — посилаємось завжди.
- Якщо новина прийшла від українських конкурентів, наша стаття має бути повнішою за їхню: додатковий ресьорч — першоджерело, оригінальне іноземне інтерв'ю, передісторія, цифри, що було раніше. Переписати їхній текст іншими словами — заборонено.
- Зовнішні посилання: першоджерело і не більше 2 світових медіа. Жодних посилань на українські медіа, магазини й каталоги.
- Рубрика — одна. Внутрішні посилання — лише на наші статті. Теги не ставимо і на сторінки тегів не посилаємось: системи тегів на сайті поки немає.`;

/**
 * Наша добавка: то, чего нет у конкурентов. Нужна ли и какая — решает модель по смыслу новости и угла, без чередования
 * и без квот (решение владельца 29.10: «не рандомные вставки»). Самодостаточной новости добавка не нужна — type "none".
 * Формат Discover не меняется: добавка — один-два абзаца или небольшой блок, а не новый раздел-справочник.
 */
export const ADDONS: Record<string, { label: string; what: string }> = {
  backstory: { label: "Передісторія", what: "що було раніше і чому це сталося саме зараз (1 абзац)" },
  compare: { label: "Тоді і зараз", what: "порівняння з тим, як герой виглядав чи діяв у схожий момент раніше" },
  ua: { label: "Український кут", what: "хто з українських зірок носив схоже, пережив схоже або як це сприйняли в Україні" },
  details: { label: "Розбір деталей", what: "бренд, модель, ціна, де знайти схоже в Україні — коротким списком" },
  reaction: { label: "Реакція мережі", what: "що пишуть у коментарях і соцмережах: 1–2 характерні цитати" },
  repeat: { label: "Як повторити", what: "лише для б'юті, моди й догляду: 2–3 практичні кроки — як повторити образ чи макіяж, який відтінок або засіб, чим замінити дешевше" },
  numbers: { label: "Цифри", what: "1–3 цифри, що дають масштаб: скільки років, яка за ліком, скільки коштує" },
  examples: { label: "Схожі приклади", what: "2–3 схожі образи чи випадки як приклади, кожен одним реченням" },
  quote: { label: "Головна цитата", what: "одна сильна пряма цитата героя з першоджерела з коротким поясненням контексту" },
};
const ADDON_KEYS = Object.keys(ADDONS);

/**
 * Как пишут украинские конкуренты, чьи тексты расходятся по 4–8 изданиям (замер 29.10.2026 по 55 статьям viva, tsn, focus,
 * glavred, 1plus1, hmstudio, 24tv): 250–400 слов, 9–15 абзацев по 1–3 предложения, 1–2 H2, 1–2 вставки поста героя,
 * прямые цитаты героя, концовка «Нагадаємо, …» со ссылкой на прошлую новость. Заголовки: имя + глагол действия
 * (показала, розповіла, зізналася, народила), цитата героя в начале, деталь перед героем, возраст или число; медиана 78 знаков.
 */
const HEADLINE_PATTERNS = `П'ять робочих схем заголовка (кожен варіант — інша схема, не «Герой: подія» п'ять разів):
1. Ім'я + дієслово дії + конкретика: «Катерина Тишкевич народила сина: перші сімейні фото й незвичне ім'я».
2. Деталь спочатку, герой далі: «У жакеті Zara та з годинником від Вільяма: Кейт Міддлтон зустрілася з Меліндою Гейтс».
3. Цифра або вік: «72-річний Андрій Макаревич уп'яте став батьком», «Блондинка з +30 кг: Ліза Колношенко показала себе 3 роки тому».
4. Цитата героя + хто і про що — лише якщо сама цитата і є новиною: «"Цей діагноз я пережила": Сумська висловилася про трагедію Федишин».
5. Контекст-гачок без приховування: «Українська акторка, яка лежала в комі, народила первістка» — інтрига з фактів, не з натяків.
Дієслова, що працюють: показала, розповіла, зізналася, відповіла, народила, розійшлася, повернулася, вийшла. Дієслова-оцінки заборонені: здивувала, вразила, підкорила, приголомшила, зачарувала.`;

/**
 * Чем цеплять без кликбейта (замечание владельца 29.10: «тайтлы очень слабые, можно же байтить без кликбейта»).
 * Интрига из факта, а не из утаивания: заголовок уже отвечает «что случилось», но добавляет деталь, из-за которой хочется узнать как.
 */
const BAIT_RULES = `Як чіпляти без клікбейту. Плоский заголовок («Монфіс про розлучення зі Світоліною», «Тишкевич народила сина») ніхто не клікає: він повідомляє, але не чіпляє. Клікбейт («ви не повірите», «шок», питання, трикрапка) Discover ріже. Між ними — гачок із факту: заголовок уже каже, що сталося, і додає одну деталь, яка змушує відкрити текст, щоб дізнатися як саме. Прийоми (у кожному варіанті — інший):
- найгостріші слова самого героя в лапках: «Я менше їм, усе здається гірше»: Монфіс про розлучення зі Світоліною;
- контраст або несподівана пара: «Сукня за 2 000 $ і кеди з ринку», «40-річний Монфіс плаче на стрімі»;
- конкретна цифра, вік, термін, сума: «вперше за 5 років», «через 10 днів після весілля», «+30 кг»;
- деталь, якої ніхто не чекав: ім'я дитини, бренд за копійки, хто сидів поруч, що відповів чоловік;
- наслідок або ставка: що це змінює для героя («перший турнір після розриву», «спершу зняла каблучку»);
- зміна стану: «вперше», «нарешті», «після року мовчання», «повернулася», «назвала причину».
Перевірка: прибери ім'я героя — чи лишилося те, заради чого відкривати? Якщо лишилося тільки «про розлучення», «показала образ», «розповіла про сина» — слабко, переписуй. У Title та Description гачок обов'язковий так само, як у H1: Title — не обрізаний H1, а свій варіант із іншим прийомом; Description — не переказ H1, а друга деталь або цитата, якої в заголовку немає.`;

/** Шаблоны текста ИИ, которые выдают машинный текст: запрещаем и в ТЗ, и в статье. */
const ANTI_AI = `Пиши як живий редактор, не як ШІ. Заборонено:
- кліше: «варто зазначити», «варто відзначити», «не секрет, що», «справжня ікона стилю», «у світі моди», «справжній фурор», «підкорила мережу», «не залишила байдужими», «вкотре довела», «неймовірний», «бездоганний», «приголомшливий», «ідеальний вибір», «відіграє ключову роль», «у сучасному світі», «отже», «таким чином», «на завершення», «ця історія доводить», «соцмережі вибухнули», «розбурхала мережу», «фанати в захваті», «зіркова пара», «світська левиця», «зірка з мільйонною армією шанувальників»;
- дієслова-оцінки замість фактів: «здивувала», «вразила», «підкорила», «зачарувала», «приголомшила», «продемонструвала» — замість них: показала, розповіла, одягла, написала, вийшла;
- конструкції: «не просто…, а…», «це не лише…, а й…», перелік рівно з трьох прикметників чи пунктів, риторичне питання в кожному блоці, підсумковий абзац-мораль чи «висновок», звертання «дорогі читачки», абзац-заклик «а як вам?», «діліться в коментарях»;
- однакові абзаци й речення однакової довжини: чергуй короткі (3–6 слів) і довші речення; не починай два абзаци поспіль однаково; не починай кожен абзац з імені героя;
- зайві тире, двокрапки й списки там, де можна сказати реченням; жирний шрифт для «важливих» слів;
- загальні слова замість деталі: не «стильний образ», а що саме (колір, крій, бренд, де і коли); не «емоційний допис», а що написала.
Починай не з загальної фрази, а з факту, деталі, сцени, цитати або цифри. Фінал — «Нагадаємо, …» про конкретну попередню подію з героєм, якщо така є в ТЗ чи джерелах; якщо немає — закінчуй цитатою героя або фактом. Ніколи — мораллю чи узагальненням.`;

/** 3 угла с форматом (кнопка «+ ТЗ для сайта»); taken — углы, уже взятые для других наших сайтов, их не повторяем. */
export async function makeAngles(ctx: AiCtx, st: NewsSettings, c: ClusterForAi, ours: OurArticle[], taken: string[] = []): Promise<{ angles: Angle[]; competitorsAngle: string; gaps: string[] }> {
  const system = `Ти шеф-редактор українського жіночого медіа для Google Discover. Про сайт: ${st.siteAbout}
${DISCOVER_RULES}

Формати статті (format → коли доречний, обсяг):
${FORMAT_KEYS.map((k) => `- ${k} (${FORMATS[k].label}, ${FORMATS[k].words}): ${FORMATS[k].when}`).join("\n")}

Перед тобою публікації про одну подію (українські та світові) і наші схожі статті.
1. competitors_angle: одним реченням — як подали інші.
2. gaps: 2–3 пункти — що можна додати від себе одним абзацом (не розділом).
3. angles: рівно 3 кути, перший — найлегший і найближчий до самої події; кути мають різні формати. Для кожного:
   format — один із ${FORMAT_KEYS.join(" | ")}; title — заголовок українською 60–95 символів за правилами Discover (герой у перших словах, конкретна деталь, без питання); angle — 1–2 речення, що саме пишемо і яка одна наша думка; why — чому клікнуть у Discover (герой, деталь, картинка), одним реченням; novelty і usefulness — 1–5.
${HEADLINE_PATTERNS}
${BAIT_RULES}
Кут — це факти й деталі, не мотивація чи психологія («особистісний ріст», «як пережити», «надихає»). «Наша думка» в куті — не оцінка зовнішності чи тіла («виснажена, але сяє», «схудла») і не мораль, а що це означає, що повторити, чому про це говорять. Заголовки й кути без кліше ШІ («підкорила мережу», «справжній фурор», «вкотре довела»).
Якщо в публікаціях лише загальні слова без конкретики (немає цитати, цифри, назви, дати) — перший кут усе одно найближчий до події, але в fit напиши «мало фактів: автору відкрити першоджерело».
Якщо інформаційний привід слабкий для нашої читачки (другорядна подія, герой маловідомий в Україні), скажи це в fit: «слабкий привід: …», інакше fit: «ok».
Поверни лише JSON: {"fit":"…","competitors_angle":"…","gaps":["…"],"angles":[{"format":"moment","title":"…","angle":"…","why":"…","novelty":4,"usefulness":4}]}`;
  const user = `Тема: ${c.title}\nКатегорія: ${c.category ? CATEGORY_LABELS[c.category] ?? c.category : "—"}${c.subcategory ? ` (${c.subcategory})` : ""}${c.entity ? `\nГерой: ${c.entity}` : ""}\nСигнали: ${c.signals.join("; ") || "—"}\n\nПублікації:\n${srcText(c, 700)}\n\nНаші схожі статті:\n${ours.map((o) => `- ${o.title} (${o.url})`).join("\n") || "— немає"}${taken.length ? `\n\nЦю новину вже пишуть інші наші сайти під такими кутами — не повторюй їх (ні формат+подачу, ні заголовок), запропонуй 3 інші, помітно відмінні:\n${taken.map((t) => `- ${t}`).join("\n")}` : ""}`;
  const j = await chatJson(withOp(ctx, "angles"), SLOT_BRIEF, system, user, st.briefModel, 2500);
  const angles = (Array.isArray(j.angles) ? (j.angles as Record<string, unknown>[]) : []).slice(0, 3).map((a) => {
    const f = s(a.format, 20).toLowerCase();
    const format = FORMAT_KEYS.includes(f) ? f : "news";
    return { kind: FORMATS[format].label, format, title: s(a.title, 160), angle: s(a.angle, 600), why: s(a.why, 400), novelty: n15(a.novelty), usefulness: n15(a.usefulness) };
  }).filter((a) => a.title && a.angle);
  if (!angles.length) throw new Error("Модель не предложила углы — нажмите ещё раз");
  const fit = s(j.fit, 300);
  const gaps = (Array.isArray(j.gaps) ? j.gaps : []).map((g) => s(g, 300)).filter(Boolean).slice(0, 4);
  if (fit && !/^ok\b/i.test(fit)) gaps.unshift(`⚠ ${fit}`);
  return { angles, competitorsAngle: s(j.competitors_angle, 400), gaps };
}

type BriefJson = {
  hook: string;
  summary: string;
  whyNow: string;
  lead: string;
  facts: { fact: string; source: string }[];
  blocks: { h2: string; note: string }[];
  ourTouch: string[];
  quotes: { text: string; who: string; where: string; source: string }[];
  ending: string;
  weak: string;
  addon: { type: string; text: string; points: string[] };
  askClaude: string[];
  extraResearch: string[];
  expert: { need: boolean; why: string; question: string; field: string; who: string; search: string[] };
  todo: string[];
  photos: { shot: string; file: string; alt: string; where: string }[];
  headlines: { text: string; type: string; bait: string }[];
  titles: string[];
  descriptions: string[];
  slugs: string[];
  rubric: string;
  og: string;
  dont: string[];
};

/** ТЗ по выбранному углу: короткое, под формат, с вариантами заголовков, title, description, slug и именами файлов. */
export async function makeBrief(ctx: AiCtx, st: NewsSettings, site: string, cIn: ClusterForAi, angle: Angle, ours: OurArticle[], summaryUk: string | null, research?: ClusterResearch | null): Promise<string> {
  let c = cIn;
  const fmt = FORMATS[angle.format ?? "news"] ?? FORMATS.news;
  const addonList = ADDON_KEYS;
  const system = `Ти шеф-редактор українського жіночого медіа ${site} для Google Discover. Про сайт: ${st.siteAbout}
${DISCOVER_RULES}
Стиль редакції (коротко): ${st.houseStyle.split("\n").slice(0, 3).join(" ")}

Склади коротке ТЗ для автора. Формат: ${fmt.label} (${fmt.words}) — ${fmt.when}. Пиши українською. Факти лише з публікацій (номер джерела). Нічого не вигадуй: чого нема в джерелах — у todo як завдання автору перевірити.${c.entity ? `\nІм'я героя пиши саме так, як у нашому списку: «${c.entity}» — у заголовках, Title і alt.` : ""}
Кожна публікація позначена [UA] — український конкурент, або [світ] — іноземне медіа. У лід, цитати й факти не вписуй «як пише …» про [UA]: звідки відомо — це першоджерело (Instagram героя, інтерв'ю, заява) або [світ]-медіа.
${ANTI_AI}
Це правило і для твого ліду, підзаголовків і заголовків у ТЗ.
${HEADLINE_PATTERNS}
${BAIT_RULES}

Як побудовані тексти, що розходяться по українських виданнях (бери за основу, не за шаблон): лід у 1–2 речення з фактом і джерелом («про це вона написала в Instagram») → що саме сталося з точною цитатою героя та вставкою поста → один абзац контексту (що було раніше, хто герой для тієї, хто не знає) → наша добавка чи думка експерта, якщо є → фінал «Нагадаємо, …» з посиланням на попередню новину про героя. Прямі цитати героя — обов'язкова частина новини про зірку: витягни з публікацій 1–3 точні цитати (дослівно, у лапках, з номером джерела); іноземну — переклади й познач.
Якщо в публікаціях менше трьох конкретних фактів (цитата, цифра, дата, назва, ім'я) і лише загальні слова («вражаючі показники», «здивувала образом») — у weak напиши, чого саме бракує, і що автору відкрити (пост героя, першоджерело). Не маскуй порожнечу красивими словами.

Стаття не має бути переказом: її відрізняє наш кут, власна подача й деталі. «Наша добавка» — те, чого немає в публікаціях конкурентів, — лише якщо вона справді посилює саме цю новину. Спершу подумай, чого бракує читачці в чужих текстах про цю подію, і тільки тоді обери тип. Якщо новина самодостатня (подія сама по собі сильна, усе головне вже є, будь-яка вставка буде штучною) — добавки не треба: type "none" і в text коротко чому. Не додавай нічого «для різноманіття». Добавка — лише те, чого НЕМАЄ в публікаціях: цитата чи факт, що вже є в джерелах, — це просто частина новини, не добавка. Для багатьох коротких новин добавка не потрібна, і це нормально.
Типи добавок:
${addonList.map((k) => `- ${k} (${ADDONS[k].label}): ${ADDONS[k].what}`).join("\n")}
Добавка складається з фактів і деталей, а не з мотивації, психології чи порад про життя («як пережити», «особистісний ріст», «надихає жінок» — заборонено). Для новин про зірок зазвичай найсильніші передісторія, тоді і зараз, цифри, цитата.
Добавка — один-два абзаци або короткий блок у межах формату, не окремий довідник.
Якщо для добавки потрібне те, чого немає в публікаціях (текст чи скриншот поста, цитата з відео, фото, ціна), — це обов'язково пункт у ask_claude: що саме знайти і де. Факти для неї — лише з публікацій; чого бракує, автор знайде сам (ask_claude або todo).
«Думка експерта» (поле expert) — окремий блок із цитатою визнаного фахівця, яку Claude знайде сам: вже сказане в інтерв'ю, книзі, науковій статті, на сайті професійної організації. need=true лише там, де читачка справді хоче почути фахівця: здоров'я, тіло, вагітність, процедури й догляд, психологія стосунків і розлучень, тренд, що має історію, гроші й право. Для виходу в світ, свята, мему, привітання — need=false. Експерт може бути з будь-якої сфери, але визнаний: з іменем, професією й публікаціями, не блогер і не «експерти вважають».
Питання до експерта — конкретне, з відповіддю-фактом: що це за діагноз чи процедура і які ризики, чи шкодить це волоссю чи шкірі, що каже закон, звідки цей тренд. Загальна психологія («жіноча інтуїція», «як пережити зраду», «як довіряти собі») — need=false.
У коротких форматах (moment, news, list) — максимум одна вставка: або «наша добавка», або «думка експерта», та, що сильніша для цієї новини; друга — none / need=false. Обидві — лише в look, howto, context, і вони не повинні пояснювати одне й те саме.
Структура не за шаблоном: порядок блоків і перший абзац обирай під цю новину, щоб наші статті не були схожі одна на одну.
Головне фото (перше в photos) НЕ може бути embed-постом: його where — пресматеріали бренду/організатора, фотобанк за редакційною ліцензією або Wikimedia Commons; embed поста героя — лише для 2-го чи 3-го фото.
Поверни лише JSON:
{"summary":"суть новини 2–3 речення чистою українською: хто, що, де, коли + деталь; імена як прийнято в українських медіа",
"hook":"сама деталь-гачок одним реченням, як факт: «ім'я Даніель і перше фото з пологового», «сукня з рідкого силікону, залитого вручну». Без слів «читачка», «клікнуть», «зацікавить», «відома»",
"why_now":"одне речення — чому писати сьогодні",
"lead":"готовий лід, 2 речення: 1-ше — хто, що, коли + звідки відомо (Instagram, інтерв'ю, пресреліз); 2-ге — головна деталь, яку обіцяє заголовок. Не повторює заголовок і не містить дієслів-оцінок",
"facts":[{"fact":"…","source":1}] — 3–6 конкретних фактів: цифри, дати, назви, імена, що саме сказано; без оцінок,
"quotes":[{"text":"точна цитата дослівно українською (іноземну переклади)","who":"хто сказав","where":"де: Instagram, інтерв'ю Раміні Есхакзай, пресреліз","source":1}] — 1–3 цитати героя чи учасників, лише ті, що є в публікаціях; порожній масив, якщо цитат немає,
"weak":"порожній рядок, якщо фактів досить; інакше — чого бракує і що автору відкрити (пост героя, першоджерело, відео)",
"blocks":[{"h2":"підзаголовок-твердження з героєм або фактом (не «Про особу», не «Що відомо», не питання)","note":"що в блоці, 1 речення: який факт, яка цитата, де вставка"}] — стільки, скільки потрібно формату (момент: 1–2; новина: 2–3; розбір/підбірка: 3–5), без H3; для тексту до 300 слів H2 можна не ставити — тоді 1 блок із note «без підзаголовків»,
"ending":"фінальний абзац «Нагадаємо, …»: конкретна попередня подія з героєм (що і коли: «у вересні показала…», «раніше розповіла про…») 1 речення: спершу з розділу «Наші статті для посилань» (тоді посилання на нашу статтю), інакше з публікацій (без згадки українського медіа). Не загальна фраза на кшталт «часто обирає сміливі образи» — якщо конкретної події немає, напиши «немає: закінчити цитатою героя»",
"gap":"спершу чесно: чого конкретно бракує читачці в усіх цих публікаціях про подію, і чого в них немає; якщо головне вже є — «нічого»",
"addon":{"type":"none, якщо gap — «нічого»; інакше один із ${addonList.join(" | ")}, що закриває саме цей gap","text":"що саме додаємо і як це закриває gap, одним реченням (для none — чому добавка не потрібна)","points":["2–4 конкретні пункти: що написати в добавці; для none — порожній масив"]},
"expert":{"need":true або false,"why":"одним реченням: чому думка визнаного експерта посилить саме цю статтю, або чому не потрібна","question":"яке одне питання до експерта закриває читачці головне «а що це означає / чи це безпечно / звідки це»","field":"сфера: дерматологія, гінекологія, психологія стосунків, історія моди, стилістика, трихологія, юриспруденція, фінанси тощо","who":"який саме визнаний фахівець підходить: професія, регалії чи організація (напр. дерматолог-член American Academy of Dermatology, куратор модного музею, психотерапевт — автор книг про стосунки)","search":["2–3 пошукові запити англійською чи українською, за якими Claude знайде вже сказане експертом"]},
"ask_claude":["0–3 тезиси для автора: що знайти й дати Claude разом із ТЗ, щоб розкрити добавку (напр. скриншот поста, 2–3 фото схожих образів, посилання на відео з таймкодом, ціна з магазину). Порожній масив, якщо нічого не потрібно"],
"extra_research":["3–5 конкретних завдань додаткового ресьорчу для Claude, щоб наша стаття була повнішою за конкурентів: що знайти і де (першоджерело — пост героя чи офіційна заява; оригінальне іноземне інтерв'ю чи публікація; що було раніше з героєм і коли; цифри, дати, імена, яких немає в українських публікаціях). Обов'язково, якщо серед джерел лише українські медіа; кожне завдання — з конкретним запитом або місцем пошуку"],
"todo":["що автору перевірити, бо в джерелах цього немає"],
"photos":[{"shot":"що в кадрі","file":"ім'я файлу латиницею через дефіс з героєм і деталлю, напр. zendaya-pixie-wnba-finals.jpg","alt":"alt українською з героєм, до 110 символів","where":"де легально взяти саме цей кадр: пресматеріали бренду X / embed поста героя / фотобанк / Wikimedia Commons"}] — 2–3 фото, перше головне 1200 px+,
"headlines":[{"text":"…","type":"дія|деталь|цифра|цитата|контекст","bait":"який прийом гачка: цитата | контраст | цифра | деталь | ставка | зміна стану"}] — рівно 3 заголовки H1 60–95 символів: три різні схеми з п'яти вище, що найкраще лягають на цю новину, і три різні прийоми гачка; схему «цитата» бери лише якщо є справжня цитата, «цифра» — лише якщо є справжня цифра (вік, сума, кількість); герой у перших словах, без питань,
"titles":["рядок","рядок","рядок"] — рівно 3 рядки (не об'єкти) Title 45–65 символів: герой + гачок, кожен іншим прийомом; не обрізаний H1 і не «Герой про подію»,
"descriptions":["рядок","рядок","рядок"] — рівно 3 рядки Description: два короткі речення, разом 100–150 символів (рахуй, довші не беруть): перше — що сталося, друге — деталь або цитата, якої немає в H1; кожен варіант з іншою деталлю; без «дізнайтеся», «читайте», «подробиці в матеріалі»"],
"slugs":["3 варіанти slug транслітом, 3–6 слів, з героєм, без дат"],
"rubric":"одна рубрика","og":"сюжет OG 1200×630",
"dont":["2–4 пункти чого не робити саме в цій статті"]}`;
  // Страницы из глубокого ресёрча (поиск по герою) — дополнительные публикации с заголовком и описанием.
  const extraPages = (research?.pages ?? []).filter((p) => p.ok && p.title && !c.sources.some((x) => x.url === p.url)).slice(0, 6);
  const allSources = [...c.sources.slice(0, 8), ...extraPages.map((p) => ({ domain: p.url.replace(/^https?:\/\/(www\.)?/, "").split("/")[0], title: p.title ?? "", lead: p.lead ?? "", url: p.url, tier: "search", at: new Date() }))];
  c = { ...c, sources: allSources };
  const user = `Тема: ${c.title}${summaryUk ? `\nСуть (чернетка, перепиши чистою українською): ${summaryUk}` : ""}\nОбраний кут (${angle.kind}): ${angle.title} — ${angle.angle}\nЧому клікнуть: ${angle.why}\n\nПублікації (номер — джерело):\n${allSources.map((x, i) => `${i + 1}. [${isUaSource(x) ? "UA" : "світ"}] ${x.domain}${x.tier === "search" ? " (знайдено пошуком)" : ""} — ${x.title}${x.lead ? `: ${x.lead.slice(0, 900)}` : ""}`).join("\n")}\n\nНаші статті для посилань:\n${ours.map((o) => `- ${o.title} (${o.url})`).join("\n") || "— немає"}`;
  // Температура 0.2: решение «нужна ли добавка и какая» должно зависеть от новости, а не от случайности ответа.
  const j = await chatJson(withOp(ctx, "brief"), SLOT_BRIEF, system, user, st.briefModel, 4000, 150_000, 0.2);
  // Модель иногда отдаёт строки объектами {text, bait} по образцу headlines — берём text.
  const list = (v: unknown, max = 300) => (Array.isArray(v) ? v.map((x) => s(x && typeof x === "object" ? (x as Record<string, unknown>).text ?? (x as Record<string, unknown>).title : x, max)).filter(Boolean) : []);
  const arr = <T>(v: unknown, f: (x: Record<string, unknown>) => T) => (Array.isArray(v) ? (v as Record<string, unknown>[]).map(f) : []);
  const b: BriefJson = {
    hook: s(j.hook, 300),
    summary: s(j.summary, 700),
    whyNow: s(j.why_now, 300),
    lead: s(j.lead, 700),
    facts: arr(j.facts, (x) => ({ fact: s(x.fact, 400), source: s(x.source, 10) })).filter((x) => x.fact).slice(0, 8),
    blocks: arr(j.blocks, (x) => ({ h2: s(x.h2, 160), note: s(x.note, 300) })).filter((x) => x.h2).slice(0, 7),
    ourTouch: list(j.our_touch, 400).slice(0, 3),
    quotes: arr(j.quotes, (x) => ({ text: s(x.text, 500), who: s(x.who, 100), where: s(x.where, 120), source: s(x.source, 10) })).filter((x) => x.text).slice(0, 4),
    ending: s(j.ending, 400),
    weak: s(j.weak, 400),
    addon: (() => {
      const a = (j.addon ?? {}) as Record<string, unknown>;
      const t = s(a.type, 20).toLowerCase();
      return { type: t === "none" || ADDON_KEYS.includes(t) ? t : "", text: s(a.text, 300), points: t === "none" ? [] : list(a.points, 300).slice(0, 5) };
    })(),
    askClaude: list(j.ask_claude, 300).slice(0, 3),
    extraResearch: list(j.extra_research, 300).slice(0, 6),
    expert: (() => {
      const e = (j.expert ?? {}) as Record<string, unknown>;
      const need = e.need === true || e.need === "true";
      return { need, why: s(e.why, 300), question: s(e.question, 300), field: s(e.field, 120), who: s(e.who, 300), search: list(e.search, 160).slice(0, 3) };
    })(),
    todo: list(j.todo, 300).slice(0, 5),
    photos: arr(j.photos, (x) => ({ shot: s(x.shot, 200), file: s(x.file, 80).toLowerCase().replace(/[^a-z0-9.-]+/g, "-"), alt: s(x.alt, 160), where: s(x.where, 200) }))
      .filter((x) => x.shot)
      .slice(0, 4)
      // Главное фото не может быть embed-постом: правило повторяем кодом, модель его иногда игнорирует.
      .map((p, i) => (i === 0 && /embed|вбудов|пост героя|instagram|facebook|threads/i.test(p.where) ? { ...p, where: "пресматеріали бренду/організатора, фотобанк за редакційною ліцензією або Wikimedia Commons (embed поста — лише як вставка в тексті, не головне фото)" } : p)),
    headlines: arr(j.headlines, (x) => ({ text: s(x.text, 120), type: s(x.type, 20), bait: s(x.bait, 20) })).filter((x) => x.text).slice(0, 6),
    titles: list(j.titles, 120).slice(0, 4),
    descriptions: list(j.descriptions, 220).slice(0, 4),
    slugs: list(j.slugs, 100).map((x) => x.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-|-$/g, "")).filter(Boolean).slice(0, 4),
    rubric: s(j.rubric, 60),
    og: s(j.og, 300),
    dont: list(j.dont, 300).slice(0, 5),
  };
  // Короткий формат держит одну вставку: если модель дала и добавку, и эксперта — оставляем эксперта (его модель не придумает за автора).
  if (["moment", "news", "list"].includes(angle.format ?? "news") && b.expert.need && b.addon.type && b.addon.type !== "none") {
    b.addon = { type: "none", text: "у короткому форматі вже є думка експерта — друга вставка зробить текст важким", points: [] };
  }
  return renderBrief(site, st, c, angle, fmt, b, ours, summaryUk, research ?? null);
}

/**
 * Украинское медиа — прямой конкурент (решение владельца 30.10): на него не ссылаемся и не упоминаем.
 * Мировое — можно: мы первые в Украине. Страницы из поиска — по домену (.ua и украинские сайты без .ua).
 */
const UA_DOMAINS = /\.ua$|(^|\.)(lux\.fm|glavred\.net|obozrevatel\.com|novyny\.live|korrespondent\.net|expres\.online|zaxid\.net|womanel\.com|bigmir\.net)$/i;
const isUaSource = (x: { tier: string; domain: string }) => (x.tier === "world" ? false : x.tier === "search" ? UA_DOMAINS.test(x.domain) : true);

const srcRef = (c: ClusterForAi, ref: string) => {
  const x = c.sources[Number(ref) - 1];
  return x ? ` (джерело ${ref}, ${x.domain}${isUaSource(x) ? ", UA — не згадувати" : ""})` : "";
};
const check = (text: string, min: number, max: number) => (text.length < min ? `⚠ ${text.length}, замало` : text.length > max ? `⚠ ${text.length}, забагато` : `${text.length}`);
/** Обороты ИИ, которые модель иногда пишет вопреки запрету: помечаем в ТЗ, чтобы автор и Claude их не повторили. */
const AI_PHRASES = [/не просто\b/i, /не лише\b.*а й/i, /варто (зазначити|відзначити)/i, /не секрет,? що/i, /справжн(я|ій) (ікона|фурор)/i, /у світі моди/i, /підкорил[аи] мережу/i, /не залишил[аи] байдуж/i, /вкотре довел/i, /неймовірн/i, /бездоганн/i, /приголомшлив/i, /ідеальн(ий|е) вибір/i, /ключову роль/i, /особистісн(ий|ого) р(і|о)ст/i, /надихн?(е|ає|ути)/i, /здивувал[аи]\b/i, /вразил[аи]\b/i, /зачарувал[аи]/i, /продемонструвал[аи]/i, /розбурхал[аи]/i, /соцмережі вибухнули/i, /фанати в захваті/i, /світськ(а|ої) левиц/i, /ця історія доводить/i, /зіркова пара/i];
const aiMark = (t: string) => {
  const hit = AI_PHRASES.map((re) => t.match(re)?.[0]).filter(Boolean);
  return hit.length ? ` ⚠ шаблон ШІ: «${hit.join("», «")}» — переписати` : "";
};
const clickbait = (t: string) =>/шок|сенсац|не повірит|\.\.\.|…|!{2,}/i.test(t);
/** Плоский заголовок: нет ни цифры, ни цитаты, ни глагола действия, ни двоеточия с деталью — одно «Герой про подію». */
const FLAT_VERBS = /показа|розпові|зізна|відпові|народи|розійш|поверну|вийш|назва|поясни|написа|одягн|заяви|визна|оголоси|відреагува|з'яви|зня[лв]|плаче|сказа/i;
const flat = (t: string) => !/\d/.test(t) && !/[«"„]/.test(t) && !FLAT_VERBS.test(t) && !/вперше|нарешті|після|замість|разом/i.test(t);
const CTA = /дізнайтес|читайте|подробиці|детальніше|у матеріалі/i;

function renderBrief(site: string, st: NewsSettings, c: ClusterForAi, angle: Angle, fmt: { label: string; words: string }, b: BriefJson, ours: OurArticle[], summaryUk: string | null, research: ClusterResearch | null): string {
  // Лимит Title не режем под суффикс Yoast: с « - Beauty Daily UA» оставалось 42 знака и заголовки выходили плоскими. Суффикс для новин выключает владелец.
  const titleMax = 65;
  const onlyUa = c.sources.slice(0, 8).every(isUaSource);
  // Герой в заголовке: сравниваем основы слов с поправкой на варианты транслитерации (Періс/Паріс, Гілтон/Хілтон).
  const fold = (s: string) => s.toLowerCase().replace(/[’'ʼ]/g, "").replace(/[іїи]/g, "и").replace(/[єе]/g, "е").replace(/[гґх]/g, "х").replace(/[ая]/g, "а").replace(/[уюо]/g, "о");
  const hero = c.entity ? c.entity.split(" ").filter((w) => w.length > 2).map((w) => fold(w).slice(1, 5)) : [];
  const heroIn = (t: string) => !hero.length || hero.some((h) => h.length >= 3 && fold(t).includes(h));
  const hl = (t: string) => `${t} — ${check(t, 55, 100)}${clickbait(t) ? " ⚠ клікбейт" : ""}${/\?\s*$/.test(t) ? " ⚠ питання: Discover ріже заголовки-питання" : ""}${heroIn(t) ? "" : " ⚠ без героя"}${flat(t) ? " ⚠ плоский: немає гачка (цифра, цитата, дія, деталь)" : ""}${aiMark(t)}`;
  // Конкретных фактов мало — ТЗ честно говорит об этом в самом верху, а не прячет за гладким текстом.
  const concrete = b.facts.filter((f) => /\d|«|"|[A-Z][a-z]{2,}/.test(f.fact)).length + b.quotes.length;
  const weakLine = b.weak || (concrete < 3 ? "у публікаціях мало конкретики (цитат, цифр, назв) — відкрий першоджерело й пост героя, без них текст буде порожнім" : "");
  const lines: string[] = [
    `# ТЗ (${fmt.label}, ${fmt.words}): ${b.headlines[0]?.text || angle.title}`,
    "",
    `> Напиши статтю для ${site} за цим ТЗ. Це матеріал для Google Discover: легкий, короткий, з героєм у заголовку. Спершу відкрий усі посилання з розділу «Джерела» і першоджерело (пост героя, інтерв'ю): ТЗ дає лише витяги, точні цитати, цифри й дати бери з оригіналів. Лише факти з джерел і матеріалів, які автор додав до ТЗ${b.todo.length ? "; що в «Автору перевірити» — знайди і підтверди або прибери" : ""}.${b.addon.type && b.addon.type !== "none" ? " Обов'язково розкрий «Нашу добавку»." : ""} Це не переказ чужої новини: свої слова, своя подача, цитати дослівно. Спершу зроби «Додатковий ресьорч»: наша стаття має бути повнішою, ніж у будь-якого конкурента. Українські медіа з «Джерел» не згадуй і не став на них посилань — це конкуренти; іноземні медіа й першоджерело — можна. Відповідь — за розділом «Формат відповіді» в кінці: чистий HTML для WordPress + метатеги, після постредактури.`,
    "",
    ...(weakLine ? [`> ⚠ Слабка фактура: ${weakLine}`, ""] : []),
    "## Суть",
    b.summary || summaryUk || c.title,
    "",
    "## Гачок і чому зараз",
    `- Гачок: ${b.hook || angle.why}`,
    `- Чому зараз: ${b.whyNow || "подія свіжа, конкуренти вже пишуть"}`,
    `- Кут (${angle.kind}): ${angle.angle}`,
    "",
    "## Лід (готовий, можна правити)",
    b.lead ? `${b.lead}${aiMark(b.lead)}` : "—",
    "",
    "## Факти",
    ...(b.facts.length ? b.facts.map((f) => `- ${f.fact}${srcRef(c, f.source)}`) : ["- Беріть факти лише з джерел нижче."]),
    "",
    "## Цитати героя (дослівно, у лапках, у тексті обов'язково)",
    ...(b.quotes.length ? b.quotes.map((q) => `- «${q.text}» — ${q.who}${q.where ? `, ${q.where}` : ""}${srcRef(c, q.source)}`) : ["- У публікаціях прямих цитат немає: відкрий пост героя чи інтерв'ю і візьми 1–2 дослівно; якщо їх нема — пиши без цитат, не вигадуй."]),
    "",
    `## Структура (${b.blocks.length} ${b.blocks.length === 1 ? "блок" : "блоки"}, ${fmt.words})`,
    "Лід 1–2 речення → що сталося з цитатою і вставкою → абзац контексту → добавка чи експерт, якщо є → фінал «Нагадаємо». Абзаци по 1–3 речення.",
    ...b.blocks.map((o, i) => `${i + 1}. **${o.h2}** — ${o.note}${aiMark(o.h2)}`),
    `${b.blocks.length + 1}. **Фінал** — ${b.ending || "«Нагадаємо, …»: одна попередня новина про героя з посиланням на нашу статтю."}`,
    "",
    ...(b.addon.type === "none"
      ? [`## Наша добавка: не потрібна${b.addon.text ? ` — ${b.addon.text}` : ""}`, "Новина самодостатня: пишемо її сильно й коротко, без штучних вставок."]
      : b.addon.type
      ? [`## Наша добавка: ${ADDONS[b.addon.type].label}${b.addon.text ? ` — ${b.addon.text}${aiMark(b.addon.text)}` : ""}`, "Те, чого немає в конкурентів: один-два абзаци або короткий блок, не окремий розділ.", ...b.addon.points.map((x) => `- ${x}${aiMark(x)}`)]
      : ["## Наш штрих (один абзац на пункт, не розділ)", ...(b.ourTouch.length ? b.ourTouch : b.addon.points.length ? b.addon.points : ["Одна порада або український контекст від редакції."]).map((x) => `- ${x}`)]),
    "",
    ...(b.expert.need && b.expert.question
      ? [
          `## Думка експерта (Claude знаходить сам)`,
          `- Навіщо: ${b.expert.why || "читачка хоче почути фахівця"}`,
          `- Питання: ${b.expert.question}`,
          `- Хто підходить: ${b.expert.who || b.expert.field}${b.expert.field && b.expert.who ? ` (сфера: ${b.expert.field})` : ""}`,
          ...(b.expert.search.length ? [`- Де шукати: ${b.expert.search.map((q) => `«${q}»`).join(", ")}`] : []),
          "- Правила: лише вже сказане реальним визнаним фахівцем (інтерв'ю, книга, наукова стаття, сайт професійної організації) — з ім'ям, професією і посиланням на першоджерело. Цитату не вигадувати, не переказувати своїми словами від імені експерта, не приписувати чужі слова; іноземну цитату перекласти й позначити «переклад редакції». Без медичних призначень і діагнозів героям. Не знайшов надійного джерела — блоку не буде, скажи про це автору одним рядком після метатегів.",
          "- Автору: відкрити посилання й переконатися, що цитата там справді є.",
          "",
        ]
      : []),
    `## Додатковий ресьорч (Claude робить сам, до написання)${onlyUa ? " — новина лише в українських конкурентів" : ""}`,
    onlyUa
      ? "Про подію поки пишуть тільки українські конкуренти. Посилатися на них не можна, тож усе, що потрапить у текст, треба підтвердити першоджерелом і додати те, чого в них немає:"
      : "Щоб стаття була повнішою за конкурентів (нові факти, першоджерело, контекст), знайди:",
    ...(b.extraResearch.length ? b.extraResearch : ["першоджерело: пост героя, офіційну заяву чи інтерв'ю — звідти точні цитати й дата", "що було раніше з героєм і коли (для абзацу контексту та «Нагадаємо»)", "цифри, імена, дати, яких немає в українських публікаціях"]).map((x) => `- ${x}`),
    "- Знайдене — у текст як факти з посиланням на першоджерело або іноземне медіа; українські медіа не згадувати. Не знайшов підтвердження — факт не використовуй.",
    "",
    "## Що дати Claude разом із ТЗ (автору)",
    ...(b.askClaude.length ? b.askClaude.map((x) => `- ${x}`) : ["- Нічого додатково не потрібно: усе є в ТЗ."]),
    "",
  ];
  if (b.todo.length) lines.push("## Автору перевірити (у джерелах цього немає)", ...b.todo.map((x) => `- ${x}`), "");
  lines.push(
    "## Фото (для редакції; у HTML не вставляти — фото ставимо самі)",
    "- Головне фото: 1200 px+ по ширині, 16:9, обличчя героя великим планом з емоцією або жива сцена (так виглядають картки, що збирають кліки); без колажів, логотипів і тексту.",
    ...b.photos.map((p, i) => `${i + 1}. ${p.shot}${i === 0 ? " — головне, 1200 px і ширше, 16:9, герой у центрі" : ""}\n   файл: \`${p.file || "hero-detail.jpg"}\` · alt: ${p.alt}${p.where ? `\n   звідки: ${p.where}` : ""}`),
    "- Права: головне фото — лише пресматеріали, фотобанк за ліцензією, Wikimedia Commons (CC) або власна зйомка; пост героя — embed-кодом. ЗАБОРОНЕНО брати фото з Daily Mail, Page Six, People та інших сайтів-джерел: це знімки агентств, за них виставляють рахунки.",
    "- Якщо подія існує лише в пості героя (фото з пологового, домашнє відео, селфі): головне фото — інший ліцензійний кадр героя (портрет з пресматеріалів, фотобанку чи Wikimedia Commons), а сам пост — вставкою в тексті. Поки знімок не обрано, у підписі заглушка «підставити джерело й ліцензію».",
    "- Під кожним фото — підпис із джерелом і ліцензією: «Фото: пресслужба Skims», «Фото: Wikimedia Commons / Автор, CC BY-SA 4.0». Підпис «Фото: dailymail.com» = порушення.",
    "",
    "## Заголовки H1 (3 варіанти, оберіть один)",
    "Гачок із факту, не з приховування: заголовок каже, що сталося, і додає деталь, заради якої відкривають. Прибери ім'я героя — має лишитися причина клікнути.",
    ...b.headlines.map((h) => `- [${h.type || "варіант"}${h.bait ? ` · ${h.bait}` : ""}] ${hl(h.text)}`),
    "",
    `## Title (3 варіанти, 45–${titleMax}${st.titleSuffix ? `; сайт дописує «${st.titleSuffix}» — для новин суфікс у Yoast вимкнути, інакше Google обріже` : ""}; Discover часто показує og:title замість H1 — у Yoast задай og:title = H1)`,
    ...b.titles.map((t) => `- ${t} — ${check(t, 45, titleMax)}${clickbait(t) ? " ⚠ клікбейт" : ""}${heroIn(t) ? "" : " ⚠ без героя"}${flat(t) ? " ⚠ плоский: немає гачка" : ""}${aiMark(t)}`),
    "",
    "## Description (3 варіанти, 110–155: що сталося + деталь чи цитата, якої немає в H1)",
    ...b.descriptions.map((d) => `- ${d} — ${check(d, 110, 155)}${CTA.test(d) ? " ⚠ заклик «дізнайтеся/читайте» — замінити деталлю" : ""}${flat(d) ? " ⚠ плоский: немає деталі" : ""}${aiMark(d)}`),
    "",
    "## Slug",
    ...b.slugs.map((x) => `- ${x}${x.split("-").length > 7 ? " ⚠ довгий" : ""}`),
    "",
    `## Рубрика, OG`,
    `- Рубрика: ${b.rubric || "—"}`,
    `- OG 1200×630: ${b.og || "те саме, що головне фото"}`,
    "- Технічно: robots max-image-preview:large; schema NewsArticle, не Article (у Yoast: тип сторінки для рубрики новин → NewsArticle), headline, image 16:9 / 4:3 / 1:1, datePublished, dateModified, author; article:published_time з таймзоною.",
    "- Зовнішні посилання: першоджерело + не більше 2 іноземних медіа; без українських медіа (конкуренти), магазинів, каталогів і сторінок тегів.",
    "",
    "## Чого не робити",
    ...(b.dont.length ? b.dont : ["не перетворювати на довідник", "не оцінювати зовнішність", "не вигадувати ціни й назви засобів"]).map((x) => `- ${x}`),
    "",
    ...(research && (research.embeds.length || research.images.length)
      ? [
          "## Матеріали з джерел (ресьорч)",
          ...(research.embeds.length
            ? [
                "Вставки з будь-яких соцмереж (Instagram, X, Facebook, Threads, Telegram, TikTok, YouTube, Pinterest) — готовий код, вставляти у WordPress блоком «HTML»; головним фото бути не можуть:",
                ...research.embeds.flatMap((e) => [`- ${e.kind}: ${e.url} (з ${e.from}${e.author ? `, @${e.author}` : ""}${e.text ? ` — «${e.text.slice(0, 120)}»` : ""})`, "```html", embedCode(e), "```"]),
              ]
            : []),
          ...(research.images.length ? ["Картинки джерел — ЛИШЕ орієнтир, що саме шукати (сюжет, ракурс); на сайт не копіювати, знайти оригінал у пресматеріалах або пості героя:", ...research.images.slice(0, 8).map((im) => `- ${im.url}${im.w ? ` (${im.w}${im.h ? `×${im.h}` : " px"})` : ""} — ${im.from}`)] : []),
          "",
        ]
      : []),
    "## Внутрішні посилання",
    ...(ours.length ? ours.map((o) => `- [${o.title}](${o.url})`) : ["- Наших статей про героя ще немає."]),
    `- Ще 1–2 дотичні наші статті знайди сам у карті сайту https://${site}/sitemap_index.xml (розділи post-sitemap): за героєм, брендом або темою; посилання лише на справді дотичне. Лише на статті — не на теги, рубрики чи пошук.`,
    "",
    "## Як писати, щоб текст не звучав як ШІ",
    ANTI_AI,
    "",
    "## Формат відповіді (обов'язково)",
    "0. Прочитай джерела за посиланнями з розділу «Джерела» і першоджерело (пост героя, інтерв'ю, пресреліз). З них — точні цитати, цифри, дати, імена; ТЗ дає лише витяги. Якщо доступу до вебу немає — пиши строго за розділами «Факти» і «Цитати героя», нічого не додумуй.",
    "1. Спочатку напиши чернетку, потім зроби постредактуру як редактор українського fashion-журналу і віддай лише фінальний текст: прибери канцелярит і кальки, повтори слів, оцінки зовнішності та кожен зворот із розділу «Як писати, щоб текст не звучав як ШІ»; абзаци по 1–3 речення, кожне речення несе факт, цитату або думку; лід не повторює заголовок; хоча б одна дослівна цитата героя в лапках; якщо в ТЗ є «Наша добавка» — вона має бути в тексті, якщо «не потрібна» — нічого не вигадуй від себе; фінал «Нагадаємо, …» з внутрішнім посиланням; перевір імена, бренди, дати й цифри за джерелами; тон — наш стиль редакції (довідково внизу).",
    "1а. Перед тим як віддати, перевір себе списком: (1) перші два речення дають факт із заголовка і джерело; (2) жодного слова зі списку заборонених; (3) фінал — «Нагадаємо» про конкретну подію або цитата героя, без моралі; (4) кожен факт і цифра є в джерелах; (5) заголовок 60–95 символів, герой у перших словах або одразу після цитати, без питання, і в ньому є гачок — прибери ім'я героя, має лишитися причина клікнути; (6) нічого не приписано героям чи експертам; (7) жодного <img> і жодної згадки чи посилання на українські медіа та на сторінки тегів; (8) у тексті є хоча б один факт із «Додаткового ресьорчу», якого немає в українських публікаціях.",
    "2. Віддай ГОТОВИЙ ЧИСТИЙ HTML для вставки у WordPress (блок «HTML»): лише теги <p>, <h2>, <a>, <strong>, <em>, <ul>/<li>. Без <html>/<body>, без <h1> (заголовок іде окремо), без inline-стилів, класів, <div>, <br>, markdown і коментарів. Винятки: офіційний код вставки соцмережі (Instagram blockquote.instagram-media + embed.js, X, TikTok, YouTube iframe) — як є, і блок «Думка експерта» (п. 7).",
    "3. Фото НЕ вставляй: жодних <img>, <figure> і заготовок із порожнім чи вигаданим src — редакція сама вирішить, де поставити фото. Вставляти можна лише готовий код вставки (Instagram, X, TikTok, YouTube iframe), якщо він є в ТЗ або ти знайшов справжній пост героя.",
    ...(research?.embeds.length
      ? [
          "4. Вставки з розділу «Матеріали з джерел» вбуду́й у текст як частину розповіді: абзац підводить до вставки («ось як це показала сама героїня:»), далі код вставки як є, далі абзац, що йде від побаченого. Одна вставка — якщо вони про одне й те саме; кілька — лише якщо показують різне. Вставка не замінює факт у тексті.",
        ]
      : ["4. Якщо є пост героя в Instagram чи X — вбудуй його в текст як частину розповіді (абзац-підводка, код вставки, абзац-продовження), а не наприкінці списком."]),
    "5. Посилання в тексті — лише двох видів: 1–2 наші статті з розділу «Внутрішні посилання» (<a> на природних словах усередині абзаців — ім'я героя, бренд, тема, не блоком «читайте також») і зовнішні — першоджерело або іноземне медіа (<a> з rel=\"nofollow noopener\" target=\"_blank\"). Ніяких посилань на українські медіа, на сторінки тегів, рубрик чи пошуку; адреси не вигадуй — лише ті, що є в ТЗ або ти сам відкрив.",
    "6. Після HTML окремим блоком — по 3 варіанти H1, Title і Description (кожен іншим прийомом гачка з розділу «Заголовки»: цитата, цифра, контраст, деталь, ставка; жоден не плоский «Герой про подію», жоден не питання), потім slug, рубрика, alt головного фото — кожне з одного рядка, без пояснень. Тегів не пиши. Можеш узяти варіанти з ТЗ, якщо після читання джерел не знайшов сильніших.",
    ...(b.expert.need && b.expert.question
      ? [
          "7. «Думка експерта» — рівно такою розміткою (класи вже є в стилях сайту), одним блоком у тому місці тексту, де читачка ставить це питання, не наприкінці. Абзац перед блоком підводить до питання, абзац після — повертає до героя. Цитата — 1–3 речення. Посада — коротко, чому цьому фахівцю можна вірити.\n```html\n<aside class=\"bd-expert\">\n  <p class=\"bd-expert__label\">Думка експерта</p>\n  <blockquote class=\"bd-expert__quote\"><p>Точна цитата.</p></blockquote>\n  <p class=\"bd-expert__who\"><strong>Ім'я Прізвище</strong>, професія, регалії чи організація</p>\n  <p class=\"bd-expert__src\">Джерело: <a href=\"URL першоджерела\" rel=\"nofollow noopener\" target=\"_blank\">Видання або організація, рік</a> · переклад редакції</p>\n</aside>\n```\n«· переклад редакції» — лише якщо цитату перекладено.",
        ]
      : []),
    "",
    "## Джерела",
    "Українські медіа (UA) — лише щоб прочитати факти; у тексті їх не згадувати й не посилатися. Іноземні (світ) — можна згадати й поставити посилання.",
    ...c.sources.slice(0, 8).map((x, i) => `${i + 1}. ${isUaSource(x) ? "UA" : "світ"} · [${x.domain}: ${x.title}](${x.url})${/news\.google\.com/.test(x.url) ? " — посилання Google News, часто не відкривається: знайди цю статтю на сайті видання за заголовком" : ""}`),
    "",
    "## Довідково: стиль редакції",
    st.houseStyle,
  );
  return lines.filter((l, i, a) => !(l === "" && a[i - 1] === "")).join("\n");
}

/** Наши статьи по герою или теме: публичный поиск WordPress сайта проекта (без ключа). */
export async function ourArticles(siteUrl: string, query: string): Promise<OurArticle[]> {
  if (!siteUrl || !query.trim()) return [];
  try {
    const base = new URL(/^https?:/i.test(siteUrl) ? siteUrl : `https://${siteUrl}`);
    const u = `${base.origin}/wp-json/wp/v2/posts?search=${encodeURIComponent(query.trim().slice(0, 80))}&per_page=12&_fields=link,title`;
    const r = await fetchText(u, { timeoutMs: 12_000, accept: "application/json" });
    if (!r.ok) return [];
    const j = JSON.parse(r.text) as { link?: string; title?: { rendered?: string } }[];
    // Поиск WordPress находит слова где угодно в тексте — оставляем статьи, где герой или тема есть в заголовке.
    const stems = query.toLowerCase().split(/[\s,.:;—–-]+/).filter((w) => w.length >= 4).map((w) => w.slice(0, Math.max(4, w.length - 2)));
    return (Array.isArray(j) ? j : [])
      .map((x) => ({ url: String(x.link ?? ""), title: String(x.title?.rendered ?? "").replace(/<[^>]+>/g, "").replace(/&#8217;|&rsquo;/g, "’").replace(/&#8211;/g, "–").replace(/&amp;/g, "&").trim() }))
      .filter((x) => x.url && x.title && stems.some((st) => x.title.toLowerCase().includes(st)))
      .slice(0, 3);
  } catch {
    return [];
  }
}
